pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 blockNum) public {
        vm.assume(value != 10 ether);
        vm.assume(blockNum < type(uint256).max);
        vm.roll(blockNum);
        vm.warp(1);

        vm.deal(address(this), value);
        (bool ok, ) = address(c).call{value: value}("");
        assertFalse(ok);
    }
}
